alter table public.occurrences add column if not exists driver_id uuid references public.drivers(id),add column if not exists patient_id uuid references public.patients(id),add column if not exists resolution text,add column if not exists resolved_at timestamptz,add column if not exists resolved_by uuid references public.profiles(id),add column if not exists updated_at timestamptz not null default now();
create table if not exists public.occurrence_history(id uuid primary key default gen_random_uuid(),occurrence_id uuid not null references public.occurrences(id) on delete cascade,municipality_id uuid not null references public.municipalities(id),user_id uuid references public.profiles(id),action text not null check(action in ('CREATED','UPDATED','STATUS_CHANGED')),old_status public.occurrence_status,new_status public.occurrence_status,old_data jsonb,new_data jsonb,changed_at timestamptz not null default now());
alter table public.occurrence_history enable row level security;revoke all on public.occurrence_history from anon,authenticated;grant select on public.occurrence_history to authenticated;drop policy if exists occurrence_history_select_same_municipality on public.occurrence_history;create policy occurrence_history_select_same_municipality on public.occurrence_history for select to authenticated using ((select private.current_user_role())='ADMIN'::public.user_role or municipality_id=(select private.current_user_municipality_id()));
create index if not exists occurrences_municipality_status_idx on public.occurrences(municipality_id,status,date desc);create index if not exists occurrences_driver_idx on public.occurrences(driver_id);create index if not exists occurrences_patient_idx on public.occurrences(patient_id);create index if not exists occurrence_history_occurrence_idx on public.occurrence_history(occurrence_id,changed_at desc);
create or replace function private.prepare_occurrence() returns trigger language plpgsql security invoker set search_path='' as $$begin new.updated_at=now();if new.trip_id is not null then select t.vehicle_id,t.driver_id into new.vehicle_id,new.driver_id from public.trips t where t.id=new.trip_id;end if;if new.status='RESOLVED' then if nullif(btrim(new.resolution),'') is null then raise exception 'Informe a resolução da ocorrência.';end if;if new.resolved_at is null then new.resolved_at=now();end if;if new.resolved_by is null then new.resolved_by=(select auth.uid());end if;else new.resolved_at=null;new.resolved_by=null;end if;return new;end;$$;
drop trigger if exists occurrences_prepare on public.occurrences;create trigger occurrences_prepare before insert or update on public.occurrences for each row execute function private.prepare_occurrence();
create or replace function private.record_occurrence_history() returns trigger language plpgsql security definer set search_path='' as $$declare a text;begin if tg_op='INSERT' then a:='CREATED';elsif new.status is distinct from old.status then a:='STATUS_CHANGED';else a:='UPDATED';end if;insert into public.occurrence_history(occurrence_id,municipality_id,user_id,action,old_status,new_status,old_data,new_data) values(new.id,new.municipality_id,(select auth.uid()),a,case when tg_op='UPDATE' then old.status end,new.status,case when tg_op='UPDATE' then to_jsonb(old) end,to_jsonb(new));return new;end;$$;
drop trigger if exists occurrences_record_history on public.occurrences;create trigger occurrences_record_history after insert or update on public.occurrences for each row execute function private.record_occurrence_history();